  'Globalization and Society',
  'Treat globalization as a set of connected social processes rather than a slogan: flows of people, capital, culture, data, institutions, risk, and power. Contemporary globalization grows out of older histories of conquest, trade, slavery, migration, industrial capitalism, and world-system formation. Students use theoretical tools to explain global interdependence, domination, resistance, and social change across markets, labor, states, institutions, migration, culture, inequality, cities, development, climate, movements, and the question of how societies can govern interdependence more justly.',
  $globjson${"slug": "globalization-and-society", "title": "Globalization and Society", "description": "Treat globalization as a set of connected social processes rather than a slogan: flows of people, capital, culture, data, institutions, risk, and power. Contemporary globalization grows out of older histories of conquest, trade, slavery, migration, industrial capitalism, and world-system formation. Students use theoretical tools to explain global interdependence, domination, resistance, and social change across markets, labor, states, institutions, migration, culture, inequality, cities, development, climate, movements, and the question of how societies can govern interdependence more justly.", "topics": [{"id": "16fedb51-1d5b-40fc-9caf-4b4f73714c71", "type": "topic", "title": "Defining Globalization and the Sociological Imagination", "description": "Students begin by treating globalization as a set of connected social processes rather than a slogan: flows of people, capital, culture, data, institutions, risk, and power.", "children": [{"id": "2d51bcd6-4c97-49c5-a688-73595319149f", "type": "subtopic", "title": "Globalization as process, condition, and debate", "children": [{"id": "3376039f-ca20-4e25-a80b-881612f8098e", "type": "concept", "title": "Flows and connections across borders"}, {"id": "59d49b4c-2e03-48f8-9767-859aa1033b39", "type": "concept", "title": "Compression of time and space"}, {"id": "bc5cc94b-7920-49fc-a6b8-8dd67051d91f", "type": "concept", "title": "Globalization as uneven and contested"}], "description": "Students learn to define globalization precisely and distinguish description from evaluation."}, {"id": "dc938b50-dfba-45d7-8bf7-f466020ae8d4", "type": "subtopic", "title": "Sociological imagination at global scale", "children": [{"id": "07938f63-e789-48ac-88d6-d64735a39ea3", "type": "concept", "title": "Everyday goods, food, phones, work, media, and family"}, {"id": "09b9fcb2-b833-4ebd-a1ee-93d617c3311d", "type": "concept", "title": "Biography and global political economy"}, {"id": "ba04bbde-5db8-4f34-b78b-d87c0fe71441", "type": "concept", "title": "Local-global feedback loops"}], "description": "This subtopic links personal experience to global structures, institutions, and histories."}, {"id": "3069a97b-635c-4c11-9c12-6d1af0542f32", "type": "subtopic", "title": "Methods for studying globalization", "children": [{"id": "6a471cd1-1ccf-4a61-8900-d94bee0a1a66", "type": "concept", "title": "Comparative cases and historical process tracing"}, {"id": "79c5e626-a977-4eb0-9400-951f63ea589b", "type": "concept", "title": "Global indicators and data literacy"}, {"id": "f47894f7-75a6-4667-baa9-22da09dc100b", "type": "concept", "title": "Ethnography, interviews, maps, and media analysis"}], "description": "Students practice using mixed evidence instead of relying on abstract generalization."}]}, {"id": "27caea5f-2679-4ab5-8114-e69a2c1cb6bb", "type": "topic", "title": "Historical Origins: Empire, Capitalism, Colonialism, Trade, and Modernity", "description": "This topic explains how contemporary globalization grows out of older histories of conquest, trade, slavery, migration, industrial capitalism, and world-system formation.", "children": [{"id": "93e91cd6-2e30-431d-a832-b9467b8f58cc", "type": "subtopic", "title": "Long histories of connection", "children": [{"id": "aae71633-67c3-4953-9fbc-b658aae62118", "type": "concept", "title": "Silk Roads, Indian Ocean, Atlantic, and colonial trade"}, {"id": "356c300b-e6a9-4e67-8fb2-3688a53f3b9d", "type": "concept", "title": "Missionaries, empires, slavery, and forced migration"}, {"id": "2594cc5e-ee0f-4bd9-85b5-42dbbc92513b", "type": "concept", "title": "Commodities, extraction, and world markets"}], "description": "Students learn that globalization has deep roots but has changed form across historical periods."}, {"id": "a98c78d6-645c-44eb-a37b-104ba7739531", "type": "subtopic", "title": "Capitalism, industrialization, and modernity", "children": [{"id": "edf2fa28-cfa2-4645-be93-cdb3b7f889d3", "type": "concept", "title": "Industrial production and wage labor"}, {"id": "9ad3f458-1bd5-4898-88bd-f903f0e82588", "type": "concept", "title": "Finance, railways, shipping, and telegraphy"}, {"id": "a179c9ee-1df8-4171-81bf-2584143e19eb", "type": "concept", "title": "Colonial division of labor"}], "description": "This subtopic explains how modern capitalism accelerated global interdependence and inequality."}, {"id": "c658ecbc-0739-4ca9-8845-aa3c2ca642a7", "type": "subtopic", "title": "Postwar and neoliberal globalization", "children": [{"id": "2cb3ab79-df13-426f-8d56-d577d8b65b29", "type": "concept", "title": "Bretton Woods, decolonization, and development"}, {"id": "4e820838-b35c-4f9a-9567-4ffbdaef1aa0", "type": "concept", "title": "Trade liberalization and structural adjustment"}, {"id": "204f9324-f164-4406-bd90-4628a32154f7", "type": "concept", "title": "Privatization, deregulation, and financialization"}], "description": "Students connect the current global order to post-1945 institutions and late twentieth-century reforms."}]}, {"id": "cf6f0138-48b6-4cb5-80e3-3abd0b23858c", "type": "topic", "title": "Theories of Globalization: World-Systems, Networks, Modernity, and Power", "description": "Students learn the major theoretical tools sociologists use to explain global interdependence, domination, resistance, and social change.", "children": [{"id": "9c1e76ad-0103-4d79-a2f1-38c834f7f343", "type": "subtopic", "title": "World-systems and dependency perspectives", "children": [{"id": "27ea1c2a-91dd-4a5d-a362-bbaf879e5954", "type": "concept", "title": "Core, semi-periphery, and periphery"}, {"id": "857d44d5-bb6e-4394-a7d7-fa0457294a88", "type": "concept", "title": "Dependency, underdevelopment, and extraction"}, {"id": "9b0f6c0d-78e4-4626-a9c7-8d9415f47d21", "type": "concept", "title": "Commodity chains and unequal exchange"}], "description": "Students use structural theories to explain unequal exchange and global hierarchy."}, {"id": "fbb96587-59e7-4fba-ac9f-7b36afd2ed90", "type": "subtopic", "title": "Network, field, and global modernity theories", "children": [{"id": "2ba47a06-93d8-4dc0-84a1-c47337e1fcac", "type": "concept", "title": "Network society and informational capitalism"}, {"id": "624dcedb-0c18-45e6-a003-628be614beb7", "type": "concept", "title": "Bourdieu: capital, field, habitus at global scale"}, {"id": "fc0f0988-8591-4264-9d1e-816ab04c523e", "type": "concept", "title": "Multiple modernities and global cultural forms"}], "description": "This subtopic gives students vocabulary for flows, fields, nodes, and transnational social spaces."}, {"id": "4f4288f8-ae97-4d58-9b46-e9d99db633b8", "type": "subtopic", "title": "Critical, feminist, postcolonial, and decolonial approaches", "children": [{"id": "a9d94971-d449-454d-8581-b939952f2e15", "type": "concept", "title": "Coloniality of power and knowledge"}, {"id": "baeeef75-066d-445b-96ee-aa768dade467", "type": "concept", "title": "Feminist political economy and care chains"}, {"id": "5470cfe7-4847-411f-bae4-f1952736d257", "type": "concept", "title": "Race, empire, and global color lines"}], "description": "Students examine how theory changes when race, gender, empire, knowledge, and standpoint are centered."}]}, {"id": "17bbe9cf-8693-4734-b9a2-cb8fc6192471", "type": "topic", "title": "Economic Globalization: Trade, Finance, Multinational Production, and Global Value Chains", "description": "This section analyzes how markets, firms, finance, and trade agreements connect everyday life to transnational economic structures.", "children": [{"id": "5781c41e-d370-4f8f-9416-a651574e6c21", "type": "subtopic", "title": "Trade and global markets", "children": [{"id": "19860783-6150-4204-9828-c346d5d09360", "type": "concept", "title": "Comparative advantage and its critics"}, {"id": "f6eab000-edcd-4d18-b8c5-af04eb06baf1", "type": "concept", "title": "Trade agreements, tariffs, and standards"}, {"id": "d170a86e-648c-4e7f-93d6-b2ec0efbf2a5", "type": "concept", "title": "Winners, losers, adjustment, and social protection"}], "description": "Students learn how trade shapes production, consumption, policy, and inequality."}, {"id": "a8dcf120-9293-4e95-ac9e-312744303e14", "type": "subtopic", "title": "Finance and global capitalism", "children": [{"id": "5c399359-5075-4066-a287-5d4e466da1ba", "type": "concept", "title": "Foreign direct investment and portfolio flows"}, {"id": "374d409b-417c-49ab-9d9a-db0d0e6c2c3b", "type": "concept", "title": "Debt, currency crises, and austerity"}, {"id": "1f830cf9-3d66-4bf3-8bd9-d7f2acecf8aa", "type": "concept", "title": "Financialization and everyday life"}], "description": "This subtopic explains how capital mobility affects states, households, crises, and development."}, {"id": "0fd52701-0fd7-467b-a451-4b2fd9d8688b", "type": "subtopic", "title": "Multinational corporations and value chains", "children": [{"id": "a3885905-1911-4db1-b8f0-faadf65020e9", "type": "concept", "title": "Lead firms, suppliers, subcontracting, and logistics"}, {"id": "35f6237a-bb78-464a-bb78-15539cbd4ecd", "type": "concept", "title": "Governance of global value chains"}, {"id": "6ef41e6a-7ac4-471b-aadc-6c82fd61693c", "type": "concept", "title": "Corporate power, tax avoidance, and regulation"}], "description": "Students connect brands and goods to production networks and power asymmetries."}]}, {"id": "14856337-9110-484b-934d-d321db56a795", "type": "topic", "title": "Global Labor, Supply Chains, Platform Work, and the Future of Work", "description": "Students examine how globalization reorganizes labor, rights, informality, care work, migration, and digital work across borders.", "children": [{"id": "bd33e014-c0db-48c2-a915-94c4e422e86a", "type": "subtopic", "title": "Labor standards and decent work", "children": [{"id": "b2f4f9a7-a477-4865-a015-9f260497695b", "type": "concept", "title": "ILO standards and labor rights"}, {"id": "c3442b4d-c5f4-4c5c-b52b-2ca588dde581", "type": "concept", "title": "Wages, safety, unions, and informal labor"}, {"id": "45804369-212e-4fc1-b3bc-406d5bc5a8e6", "type": "concept", "title": "Gendered and racialized divisions of labor"}], "description": "Students learn how global production creates both opportunity and exploitation."}, {"id": "e3a75877-01f2-40d0-b479-450aed3e3366", "type": "subtopic", "title": "Care chains and migrant labor", "children": [{"id": "d909023c-21fe-46c7-aeb0-7054a0c3cd69", "type": "concept", "title": "Domestic work, nursing, agriculture, construction, and service work"}, {"id": "c7ec7447-5bd6-4d97-9207-e6f89b083334", "type": "concept", "title": "Remittances and separated families"}, {"id": "7dd69c57-4e5c-4bd3-8319-4685ee8ba5ef", "type": "concept", "title": "Recruitment, visas, precarity, and rights"}], "description": "This subtopic links household reproduction to global labor markets and migration regimes."}, {"id": "65633ce4-0979-4158-a204-e78716a236ef", "type": "subtopic", "title": "Digital and platform labor", "children": [{"id": "c39f81d2-525c-4906-904a-9f6bd8f9df90", "type": "concept", "title": "Gig work, microwork, content moderation, and remote labor"}, {"id": "ef5443cd-1962-4cc3-b738-5ee3d8fa9c28", "type": "concept", "title": "Algorithmic management and worker control"}, {"id": "6a7fa3a0-58fa-4169-854b-8842684e016c", "type": "concept", "title": "Automation, AI, and reskilling"}], "description": "Students examine how data platforms globalize work, surveillance, and income insecurity."}]}, {"id": "99db76a9-e7b6-427c-89dc-d1fa34ba66d0", "type": "topic", "title": "Political Globalization: States, Sovereignty, Governance, and Public Goods", "description": "This topic asks how power is organized when problems cross borders but political authority remains unevenly distributed.", "children": [{"id": "41d9f136-4d2c-49b9-9340-e51263edc968", "type": "subtopic", "title": "Sovereignty under interdependence", "children": [{"id": "47434abe-07cf-44ba-bc66-5dd78e498736", "type": "concept", "title": "State capacity and policy autonomy"}, {"id": "b155e28a-0798-43d0-b63c-f418c557b21e", "type": "concept", "title": "Borders, citizenship, and jurisdiction"}, {"id": "598a53ca-7d72-467b-bc25-3c0b8bb50f19", "type": "concept", "title": "Interdependence, vulnerability, and coordination"}], "description": "Students explore how states remain central while facing cross-border problems."}, {"id": "6e249722-4520-426b-83b6-c0d136f40096", "type": "subtopic", "title": "Global public goods", "children": [{"id": "7f2ad9c3-bd32-4b2e-8c5c-af9f1d7dcaaa", "type": "concept", "title": "Free-riding and collective action"}, {"id": "6d334467-5a37-4805-aca0-22bc47568671", "type": "concept", "title": "Global commons and shared risks"}, {"id": "f01816c9-4766-4682-a2d8-d4dce376d572", "type": "concept", "title": "Funding, burden-sharing, and enforcement"}], "description": "This subtopic clarifies why climate stability, public health, financial stability, and peace require collective action."}, {"id": "29765eb7-a187-401e-8cfa-91fd0eee74ca", "type": "subtopic", "title": "Regime theory and informal governance", "children": [{"id": "cc0f0ff2-b5c2-4cc5-bee2-0e61a169de54", "type": "concept", "title": "International regimes and norms"}, {"id": "7ab815ee-5f8d-4b59-bd38-06a4a8ffffdf", "type": "concept", "title": "Clubs, summits, standards, and rankings"}, {"id": "55d8e200-265c-4cc7-bea9-982dcbe051e1", "type": "concept", "title": "Private authority and multi-stakeholder governance"}], "description": "Students learn that global governance includes formal treaties and informal networks."}]}, {"id": "e1782584-c2b2-44af-848b-a08c83adbf8e", "type": "topic", "title": "Global Institutions, NGOs, Human Rights, and Accountability", "description": "Students study the United Nations, international financial institutions, NGOs, human rights regimes, and debates over legitimacy and reform.", "children": [{"id": "b3331bec-0c03-4670-a19e-fa7592aaf16f", "type": "subtopic", "title": "United Nations and multilateral institutions", "children": [{"id": "6a389431-9764-4852-ab80-6763e2b70fd0", "type": "concept", "title": "UN agencies, Security Council, General Assembly, and treaty bodies"}, {"id": "b4ef6b91-e361-463c-b603-eb303e77cd3f", "type": "concept", "title": "World Bank, IMF, WTO, and regional organizations"}, {"id": "81f5d142-3f4e-4dfa-a016-2f02e9c92e01", "type": "concept", "title": "Mandates, funding, bureaucracy, and reform"}], "description": "Students learn how global institutions are built, what they can do, and where they struggle."}, {"id": "9a2c207a-b0c4-447c-9a83-8ea7e260ff03", "type": "subtopic", "title": "NGOs, civil society, and advocacy networks", "children": [{"id": "9997631e-84ea-4edb-8405-cc7a3ad2510f", "type": "concept", "title": "Human rights NGOs and humanitarian organizations"}, {"id": "4bc7b88f-b748-4ca8-9e08-56c0963a390a", "type": "concept", "title": "Transnational advocacy networks"}, {"id": "08a1eed1-1e9b-4d00-abfd-44ed77d16100", "type": "concept", "title": "Legitimacy, representation, and accountability"}], "description": "This subtopic examines how non-state actors shape global norms and policy agendas."}, {"id": "c7b4be73-edf2-4f5b-8c97-e37ca14c9076", "type": "subtopic", "title": "Human rights and global justice", "children": [{"id": "6858d77f-e775-482c-a962-9d13703cb0b3", "type": "concept", "title": "Rights treaties and monitoring"}, {"id": "d050bd88-ea0c-4945-afa6-17d7463075fc", "type": "concept", "title": "Humanitarian intervention and responsibility to protect"}, {"id": "cb2e267c-5ad9-4e6d-8271-7cd5f81f2dc5", "type": "concept", "title": "Critiques: selectivity, sovereignty, and power"}], "description": "Students connect universal claims to enforcement problems and political contestation."}]}, {"id": "68ac0875-61ce-4ba6-ac2d-c45d0d20b2f1", "type": "topic", "title": "Migration, Refugees, Diaspora, Transnationalism, and Citizenship", "description": "This section focuses on people on the move and the social worlds they build across borders, labor markets, households, states, and identities.", "children": [{"id": "f102ee0d-db6c-442d-ba9f-3f8f451865c4", "type": "subtopic", "title": "Migration systems and mobility regimes", "children": [{"id": "710ad55f-e89f-4001-b694-d1c459b5aa51", "type": "concept", "title": "Labor migration, student migration, refugees, and asylum"}, {"id": "2509c39a-8f1c-404e-8f22-d76d875bbcbf", "type": "concept", "title": "Border regimes, detention, and deportation"}, {"id": "631187fa-7b5d-4f33-8674-cb7dd52f476f", "type": "concept", "title": "Smuggling, trafficking, and protection"}], "description": "Students study migration as structured by labor demand, violence, policy, family, and aspiration."}, {"id": "48244542-5c43-44a1-b91e-3b34219d4362", "type": "subtopic", "title": "Transnational households and diasporas", "children": [{"id": "9a382c91-9aa9-4aa6-8bf8-16091656bfc1", "type": "concept", "title": "Remittances, care, communication, and return"}, {"id": "c05bb587-456f-4704-ba8a-1e2373cd236d", "type": "concept", "title": "Diaspora politics and homeland ties"}, {"id": "241bb16c-b0d5-4af2-ac28-897d1e59ecd8", "type": "concept", "title": "Second generation, belonging, and identity"}], "description": "This subtopic shows how migrants sustain social life across borders."}, {"id": "fc28905e-96cc-4b0f-8c88-1431d8bfa7f1", "type": "subtopic", "title": "Citizenship, integration, and exclusion", "children": [{"id": "9c69e3c0-6735-49ab-995d-1235399cbdcd", "type": "concept", "title": "Naturalization, legal status, and rights"}, {"id": "8d74576e-11c6-491e-82e1-b3e0118ddf4c", "type": "concept", "title": "Multiculturalism, assimilation, and backlash"}, {"id": "b387c96c-39dd-4044-80a1-5b2534e03322", "type": "concept", "title": "Racism, xenophobia, and sanctuary movements"}], "description": "Students analyze how states define membership and how societies negotiate difference."}]}, {"id": "07edb91a-f6d3-44db-b1e0-c43afaff8b01", "type": "topic", "title": "Cultural Globalization: Media, Religion, Consumerism, Hybridity, and Identity", "description": "Students analyze how cultural products, meanings, brands, religions, languages, and media circulate, mix, and become contested.", "children": [{"id": "6e31b11d-22f2-4e5b-9f63-713770833bbb", "type": "subtopic", "title": "Global media and cultural flows", "children": [{"id": "1da31324-6c69-4c5c-901e-e4a0f89ec148", "type": "concept", "title": "Cultural imperialism and media concentration"}, {"id": "e2327859-ac44-4e9d-aabd-abbfde42aa63", "type": "concept", "title": "Streaming, social media, and influencer economies"}, {"id": "c35bd5d8-64cb-4554-bad5-698ce01d0864", "type": "concept", "title": "News, misinformation, and public spheres"}], "description": "Students examine how images, music, news, platforms, and entertainment circulate unevenly."}, {"id": "37ff6bb8-eb99-4705-bbda-aa6300741778", "type": "subtopic", "title": "Hybridization and localization", "children": [{"id": "9e8d8303-3abe-430a-847a-d1239889c307", "type": "concept", "title": "Glocalization and cultural translation"}, {"id": "396f98a7-f48b-4f32-a130-b17889b39eee", "type": "concept", "title": "Language, food, fashion, music, and sport"}, {"id": "4480f58f-a140-47ca-a449-49f9857fc83e", "type": "concept", "title": "Appropriation, authenticity, and ownership"}], "description": "This subtopic helps students avoid simple homogenization arguments by showing adaptation and remix."}, {"id": "5eb87543-ff70-4b6e-b5bb-bb0bef6d84be", "type": "subtopic", "title": "Religion, values, and cultural conflict", "children": [{"id": "c071341d-c234-4c9d-85a9-e9cf7edc555f", "type": "concept", "title": "Religious transnationalism"}, {"id": "553572dc-f6f7-4d88-9e24-7c148ac42299", "type": "concept", "title": "Secularization and revival"}, {"id": "6b153a01-3f23-45de-8b35-38b904aeb005", "type": "concept", "title": "Moral politics, identity, and global publics"}], "description": "Students explore how globalization intensifies contact, revival, pluralism, and conflict."}]}, {"id": "42c2ed8b-f481-4ccb-a9bc-d931ef2092ab", "type": "topic", "title": "Global Inequality, Stratification, Race, Gender, Class, and Development", "description": "This topic examines durable global hierarchies and how inequality is produced through institutions, policy, labor markets, colonial legacies, and social categories.", "children": [{"id": "63969b23-f37b-4a54-91e8-35503913a5b2", "type": "subtopic", "title": "Measuring global inequality", "children": [{"id": "360c3ebe-7967-4159-a43f-68548f95a20e", "type": "concept", "title": "Income, wealth, health, education, and capabilities"}, {"id": "e5b4218b-ee69-44fb-b2a1-17e94168bb02", "type": "concept", "title": "Between-country and within-country inequality"}, {"id": "ff8c2227-1ac6-410e-98c6-944774f207f9", "type": "concept", "title": "HDI, Gini, poverty lines, and data limits"}], "description": "Students learn how inequality looks different depending on units, metrics, and data choices."}, {"id": "f41d0c92-fdaa-4a52-a1c1-984ee4647681", "type": "subtopic", "title": "Durable global hierarchies", "children": [{"id": "53e299b3-f755-4224-88b1-09b5196dc25e", "type": "concept", "title": "Class, race, caste, ethnicity, gender, and citizenship"}, {"id": "8d40f7b9-2b9f-45ea-acb9-56e28638bf57", "type": "concept", "title": "Global color line and racial capitalism"}, {"id": "d99b0e35-0894-472b-b50d-08f6f90cfb57", "type": "concept", "title": "Elites, tax havens, and concentrated wealth"}], "description": "This subtopic connects inequality to institutions, colonial legacies, policy, and social categories."}, {"id": "75b57e6d-41be-4c8e-a12b-75cf6c2578ae", "type": "subtopic", "title": "Development and social mobility", "children": [{"id": "c40f8264-9ba8-4e00-a304-f2e68af1958f", "type": "concept", "title": "Institutions, markets, policy, and geography"}, {"id": "35578257-656c-4156-b0ab-502682e04d99", "type": "concept", "title": "Education, health, gender, and social protection"}, {"id": "c34c70f3-10d2-468a-86c7-b4763b6fc896", "type": "concept", "title": "Capabilities and human development"}], "description": "Students evaluate competing explanations for poverty reduction and blocked mobility."}]}, {"id": "069d6ed4-b0ff-4cd7-8a12-6781a91107f1", "type": "topic", "title": "Global Cities, Urbanization, Housing, Infrastructure, and Spatial Inequality", "description": "Students learn why cities are key sites of global connection, migration, finance, inequality, culture, and climate vulnerability.", "children": [{"id": "e9c247d1-0efa-4637-8448-5c6d2b2726e2", "type": "subtopic", "title": "Global cities and urban networks", "children": [{"id": "a960909b-63ed-40e7-83e9-af4bb7617a55", "type": "concept", "title": "Global city theory"}, {"id": "4121a3b6-fca4-4ece-add0-5d80d3b29678", "type": "concept", "title": "Ports, airports, data centers, and logistics hubs"}, {"id": "f2a8f6b4-d527-41ef-80b2-8e8d17a90a6a", "type": "concept", "title": "Urban hierarchy and regional inequality"}], "description": "Students learn why some cities become command centers for finance, migration, culture, and logistics."}, {"id": "92155d1a-274b-4891-a6db-40749c3b7f4a", "type": "subtopic", "title": "Urban inequality and housing", "children": [{"id": "8c6488d7-fa8f-4631-8bf1-2addefe02644", "type": "concept", "title": "Gentrification, speculation, and real estate finance"}, {"id": "810e999a-e2a6-42b8-af5b-ad22303ae480", "type": "concept", "title": "Informal settlements and housing rights"}, {"id": "96a49af2-1515-4f48-b9a6-15cafe5da874", "type": "concept", "title": "Segregation, policing, and service access"}], "description": "This subtopic links global capital to local housing markets, segregation, informality, and displacement."}, {"id": "a9354ab6-c746-4aa8-b861-215ba6acdeb1", "type": "subtopic", "title": "Urban climate and infrastructure", "children": [{"id": "0ad38db3-e6fc-4364-9355-c0ed94d0b6eb", "type": "concept", "title": "Transit, water, sanitation, energy, and waste"}, {"id": "e5efa15f-625b-404d-8c6c-3224b5d277ea", "type": "concept", "title": "Heat, flooding, and climate adaptation"}, {"id": "a980b85a-f4ec-42a7-ba49-180f57f4d14b", "type": "concept", "title": "Smart cities and data governance"}], "description": "Students see cities as sites of both vulnerability and innovation in global sustainability."}]}, {"id": "8e2a0cdb-4d69-4ad9-939e-68725e52a208", "type": "topic", "title": "Development, Aid, Humanitarianism, SDGs, and Localization", "description": "This section evaluates global development and humanitarian systems through poverty, state capacity, evidence, ethics, participation, and local power.", "children": [{"id": "1c3a313d-5904-42d6-8252-6cd0de5b48ad", "type": "subtopic", "title": "Development paradigms and poverty reduction", "children": [{"id": "e8fa1f31-a60e-45d9-8ab3-d3fc64c8ef6b", "type": "concept", "title": "Growth, institutions, and state capacity"}, {"id": "114d2814-3d1a-44d8-b0a4-47aedf85e4f6", "type": "concept", "title": "Poverty traps and randomized evaluations"}, {"id": "24c98414-167e-40b2-aa7f-fe5b0ac595b6", "type": "concept", "title": "Human development and capabilities"}], "description": "Students compare modernization, dependency, capabilities, and evidence-based approaches."}, {"id": "a5cf2e65-be3f-404a-bc4d-1a6779157fc1", "type": "subtopic", "title": "Aid, humanitarianism, and fragile states", "children": [{"id": "210531bc-c05e-4100-b119-6fa9f73d99e5", "type": "concept", "title": "Aid effectiveness and donor priorities"}, {"id": "cdabf108-e9ad-4ef6-9c66-6d413b2f68cc", "type": "concept", "title": "Humanitarian response, conflict, and displacement"}, {"id": "ced273c2-c4de-4feb-be6c-72d7140304eb", "type": "concept", "title": "Corruption, accountability, and unintended effects"}], "description": "This subtopic evaluates the promises and limits of foreign assistance."}, {"id": "e3faeef9-4088-4452-af9e-c8ca57c057e9", "type": "subtopic", "title": "SDGs, localization, and ethics", "children": [{"id": "23188598-65f3-4b42-b22c-a13c314780f4", "type": "concept", "title": "Sustainable Development Goals"}, {"id": "50259592-849b-4fed-8df0-616cc0becd62", "type": "concept", "title": "Participation, local ownership, and decolonizing aid"}, {"id": "4a404dfa-79c4-49e7-a866-f4c3178151ee", "type": "concept", "title": "Monitoring, evaluation, and learning"}], "description": "Students examine development as a political and ethical process rather than a technical checklist."}]}, {"id": "0fe7ee52-1a36-42bd-a8fd-b332cab0c848", "type": "topic", "title": "Environment, Climate Change, Resource Conflict, and Environmental Justice", "description": "Students study globalization through shared ecological risk, climate governance, resource extraction, environmental inequality, and green transitions.", "children": [{"id": "d2d2a28f-d2e8-4e5b-950e-fc655ab076ff", "type": "subtopic", "title": "Climate governance and global negotiations", "children": [{"id": "c02330bf-0b31-48f6-b195-8a3b29eedfb8", "type": "concept", "title": "UNFCCC, Paris Agreement, COP process, and NDCs"}, {"id": "7d55ddf8-d888-4548-8a2b-2c04ffc758fd", "type": "concept", "title": "Mitigation, adaptation, loss and damage"}, {"id": "e44ed9e5-0bc2-45be-b384-e5e4f58833af", "type": "concept", "title": "Climate finance and burden-sharing"}], "description": "Students learn how climate change exposes the difficulties of governing shared risk."}, {"id": "cdd14d61-b3fc-4575-b701-f9e447336cf2", "type": "subtopic", "title": "Resources, extraction, and conflict", "children": [{"id": "cde1d5b2-ab54-4613-bd28-fdffdbfd17cf", "type": "concept", "title": "Oil, gas, lithium, rare earths, timber, and water"}, {"id": "a93e5ca2-da1f-43af-b581-a187b836b9c7", "type": "concept", "title": "Extractive zones and sacrifice zones"}, {"id": "d2768526-9f33-43a1-aba3-6a887f0811fd", "type": "concept", "title": "Resource scarcity, conflict, and corporate accountability"}], "description": "This subtopic connects global demand to land, water, energy, minerals, violence, and displacement."}, {"id": "34f82920-d664-4ec1-a4dd-a358e21762fb", "type": "subtopic", "title": "Environmental justice and just transitions", "children": [{"id": "8d94846e-061d-4637-9391-83a4263fd749", "type": "concept", "title": "Climate vulnerability and historical responsibility"}, {"id": "432a5131-798e-4885-b0db-358a20971d08", "type": "concept", "title": "Indigenous land rights and environmental racism"}, {"id": "9f51a47b-55b6-4d6e-b0a8-9a53e3aecd25", "type": "concept", "title": "Green jobs, energy transitions, and social protection"}], "description": "Students examine who benefits, who is harmed, and what fairness means in ecological transitions."}]}, {"id": "82c74979-58a1-4160-8408-5c673a670d8c", "type": "topic", "title": "Anti-Globalization, Alter-Globalization, Populism, and Transnational Social Movements", "description": "This topic examines resistance to globalization from labor, Indigenous, feminist, environmental, nationalist, and democratic accountability perspectives.", "children": [{"id": "2aba7de3-f354-49de-accb-acc8dc83d0df", "type": "subtopic", "title": "Anti-globalization and alter-globalization", "children": [{"id": "a4b8366a-e7d8-41e9-bfa3-60541748e53a", "type": "concept", "title": "Seattle 1999 and WTO protests"}, {"id": "66dc4f48-c7e9-4f64-a6f4-f83246034c08", "type": "concept", "title": "World Social Forum and global justice movements"}, {"id": "ee9e1de7-beb8-4b34-9593-722633cebecd", "type": "concept", "title": "Debt relief, fair trade, and labor solidarity"}], "description": "Students distinguish reactionary rejection from democratic critiques that seek different forms of global integration."}, {"id": "5c799fe4-7c68-4e2f-b882-5a211527d553", "type": "subtopic", "title": "Populism, nationalism, and backlash", "children": [{"id": "28f617b1-5ac8-4722-8ba1-64b2aef251d8", "type": "concept", "title": "Economic insecurity and status threat"}, {"id": "de99a544-76e2-4ebd-a67f-a3a4cc4b203b", "type": "concept", "title": "Borders, sovereignty, and anti-immigrant politics"}, {"id": "959efbfe-aa1d-438c-8d38-569f53948d26", "type": "concept", "title": "Authoritarianism, misinformation, and polarization"}], "description": "This subtopic analyzes political responses to inequality, migration, cultural change, and perceived loss of control."}, {"id": "7ebd0156-ad56-46b3-9546-7d7afa47091e", "type": "subtopic", "title": "Transnational movements and advocacy", "children": [{"id": "40a30d5f-30bf-4bf6-a1a4-25ace218da6e", "type": "concept", "title": "Feminist, climate, Indigenous, labor, and human rights networks"}, {"id": "dcee7ad7-3d60-4be8-8164-687af0de99e4", "type": "concept", "title": "Digital mobilization and platform risks"}, {"id": "0fcb01d3-7c2d-4146-b20e-8998f1a76904", "type": "concept", "title": "Coalitions, framing, and strategy"}], "description": "Students learn how movements coordinate across borders while negotiating difference and power."}]}, {"id": "56123609-3f71-4f97-a22d-59d1042833db", "type": "topic", "title": "Futures of Globalization: Digital Networks, AI, Pandemics, De-Risking, and Capstone Case Analysis", "description": "The course ends by asking students to analyze where globalization is going and how societies can govern interdependence more justly.", "children": [{"id": "9fb453d9-eda5-4284-ab60-376ec6f6991b", "type": "subtopic", "title": "Digital globalization and data power", "children": [{"id": "9379ef87-6eb4-4960-8007-aff336ddd29c", "type": "concept", "title": "Data centers, cloud platforms, chips, and undersea cables"}, {"id": "2f725950-2284-4da4-a09b-e8d3672aa957", "type": "concept", "title": "AI, automation, algorithmic governance, and bias"}, {"id": "1d34ef84-a6d3-443b-91e9-b1d26aba4539", "type": "concept", "title": "Digital divides and platform sovereignty"}], "description": "Students examine how digital infrastructure reshapes markets, surveillance, culture, and inequality."}, {"id": "d4665e61-df4b-4c88-a4a8-5ca5432c35b5", "type": "subtopic", "title": "Risk, resilience, and de-globalization debates", "children": [{"id": "8f14ee66-22e1-448f-b5d3-c4de0e4a9d72", "type": "concept", "title": "Pandemics and global health security"}, {"id": "17781691-1a23-4adc-a083-12488ed4075d", "type": "concept", "title": "Supply-chain resilience, friend-shoring, and de-risking"}, {"id": "78e7fc46-e8b9-477e-ac0a-f007f6d480d6", "type": "concept", "title": "Sanctions, war, debt, and geopolitical fragmentation"}], "description": "This subtopic examines whether globalization is reversing, reorganizing, or becoming more regional and securitized."}, {"id": "310f8221-0975-48b2-8842-3997d34d8825", "type": "subtopic", "title": "Capstone case analysis", "children": [{"id": "ffdebdd1-ee39-49e8-be28-86edc12de212", "type": "concept", "title": "Case options: migration corridor, supply chain, climate treaty, city, platform, or movement"}, {"id": "07877874-0180-44ad-8ab7-6d52ccf1149a", "type": "concept", "title": "Data profile, stakeholder map, and theory application"}, {"id": "efa4005c-ae96-44c0-af93-0df2684de848", "type": "concept", "title": "Final written dossier and presentation"}], "description": "Students synthesize the whole course through a case that connects theory, evidence, stakeholders, and policy choices."}]}], "dbBacked": true}$globjson$::jsonb,
